parameters.jsCode:
// Format the overdue task list for the alert message
const client = $('Get Client's Active Project').item.json;
const tasks = $json;

const today = new Date();
const lines = tasks.map(t => {
  const dueDate = new Date(t.date_deadline);
  const daysOverdue = Math.floor((today - dueDate) / 86400000);
  return `- ${t.name} (due ${t.date_deadline}, ${daysOverdue}d overdue)`;
}).join('\n');

return [{
  json: {
    client_id: client.client_id,
    odoo_discuss_channel_id: client.odoo_discuss_channel_id,
    client_email: client.email,
    client_name: client.name,
    overdue_count: tasks.length,
    alert_body: `Milestone check for ${client.name}: ${tasks.length} task(s) overdue.\n\n${lines}`
  }
}];

